(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(y*0.016-t*0.28)*14+Math.sin(x*0.021+t*0.33)*11;
  const w3 = Math.sin((x+y)*0.008+t*0.15)*20+Math.cos((x-y)*0.01-t*0.18)*15;
  const sx = x+w1+w3*0.4, sy = y+w2+w3*0.4;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*50, 0.075, 2.1],
    [340+Math.cos(t*0.45)*100, 150+Math.sin(t*0.6)*60, 0.09, 1.8],
    [240+Math.sin(t*0.28+2)*150, 100+Math.cos(t*0.42+1)*80, 0.055, 2.5],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*70, 0.11, 1.6],
    [380+Math.sin(t*0.38+4)*100, 50+Math.cos(t*0.8+2)*80, 0.065, 2.8],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*90, 0.085, 2.0],
    [60+Math.sin(t*0.55+3)*70, 130+Math.cos(t*0.65+1)*55, 0.1, 1.4],
    [420+Math.cos(t*0.42+6)*60, 200+Math.sin(t*0.58+4)*45, 0.07, 2.3]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*0.02-t*0.4)*0.3+1;
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3.1)*0.5;
  }
  const act=aS/8, inh=iS/8, harm=hS/8;
  const n1=Math.sin(sx*0.035+sy*0.022+t*0.75);
  const n2=Math.sin(sx*0.028-sy*0.038+t*1.05);
  const n3=Math.sin((sx+sy)*0.11+t*2.3)*0.25;
  const n4=Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const n5=Math.sin(sx*0.06+t*0.5)*Math.cos(sy*0.055-t*0.4)*0.15;
  const bg=(n1+n2)/2+n3+n4+n5;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral=(sp1+sp2)*0.35+sp3;
  const lap=Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.4+Math.sin((sx*0.7-sy*0.5)*0.08-t*0.6)*0.3;
  const cell=Math.tanh(lap*1.6)*0.25;
  const micro=Math.sin(sx*0.3+t*1.2)*Math.sin(sy*0.28-t*0.9)*Math.cos((sx-sy)*0.2+t*0.7)*0.12;
  const rd1=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.0);
  const rd2=Math.tanh((harm*0.4+rd1*0.6-cell+micro)*1.8);
  const rd3=Math.tanh((rd1*0.5+rd2*0.5+spiral*0.15)*2.5);
  const blend=rd3*0.55+rd2*0.3+cell*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,82,115],[25,130,130],
    [60,165,120],[160,190,70],[210,175,55],[220,130,60],
    [190,80,65],[140,45,72],[75,22,58],[30,14,50],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(rd3*Math.PI)*0.18;
  const edge=Math.abs(rd3)>0.65?1.12:Math.abs(rd3)>0.4?1.05:0.95;
  const shimmer=Math.sin(t*3+sx*0.1+sy*0.08)*0.03+1;
  const cm=[[1,0.02,0.03],[0.02,1,0.01],[0,0.03,1]];
  const cShift=Math.sin(t*0.2)*0.15;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,((r0*cm[0][0]+g0*cm[0][1]+b0*cm[0][2]+cShift*30)*lum*edge*shimmer))|0,
    Math.min(255,((r0*cm[1][0]+g0*cm[1][1]+b0*cm[1][2])*lum*edge*shimmer))|0,
    Math.min(255,((r0*cm[2][0]+g0*cm[2][1]+b0*cm[2][2]-cShift*20)*lum*edge*shimmer))|0
  ];
}
